29:    * 选中的商品列表（从缓存中获取）
30:    */
31:   @Trace
32:   selectedGoodsList: SelectedGoods[] = [];
33:   /**
34:    * 购物车列表（用于页面展示）
35:    * 优先从 cachedCarts 获取，没有则从 selectedGoodsList 转换
36:    */
37:   @Trace
38:   cartList: Cart[] = [];
39:   /**
40:    * 订单备注
41:    */
42:   @Trace
43:   remark: string = "";
44:   /**
45:    * 优惠券弹出层的显示状态
46:    */
47:   @Trace
48:   couponModalVisible: boolean = false;
49:   /**
50:    * 选中的优惠券
51:    */
52:   @Trace
53:   selectedCoupon: Coupon | null = null;
54:   /**
55:    * 商品原价（单位：元）
56:    */
57:   @Trace
58:   originalPrice: number = 0;
59:   /**
60:    * 优惠券折扣金额（单位：元）
61:    */
62:   @Trace
63:   discountAmount: number = 0;
64:   /**
65:    * 最终价格（单位：元）
66:    */
67:   @Trace
68:   totalPrice: number = 0;
69: 
70:   /**
71:    * 请求确认订单页面数据
72:    * @returns {Promise<NetworkResponse<ConfirmOrder>>} 确认订单页面数据
73:    */
74:   protected requestRepository(): Promise<NetworkResponse<ConfirmOrder>> {
75:     return this.pageRepository.getConfirmOrder();
76:   }
77: 
78:   /**
79:    * 页面出现时加载数据
80:    * @returns {void} 无返回值
81:    */
82:   aboutToAppear(): void {
83:     // 先加载缓存数据
84:     this.loadOrderCache();
85:     // 再执行网络请求
86:     super.aboutToAppear();
87:   }
88: 
89:   /**
90:    * 从缓存加载订单数据
91:    * @returns {Promise<void>} Promise<void>
92:    */
93:   async loadOrderCache(): Promise<void> {
94:     // 1. 读取购物车缓存（仅购物车页面会存储）
95:     this.cachedCarts = await this.orderCacheStoreRepository.loadCarts();
96: 
97:     // 2. 读取已选商品列表
98:     this.selectedGoodsList = await this.orderCacheStoreRepository.loadSelectedGoodsList() ?? [];
99: 
100:     // 3. 购物车列表：优先从 cachedCarts 获取，没有则从 selectedGoodsList 转换
101:     if (this.cachedCarts && this.cachedCarts.length > 0) {
102:       this.cartList = this.cachedCarts;
103:     } else {
104:       this.cartList = this.convertSelectedGoodsToCartList(this.selectedGoodsList);
105:     }
106: 
107:     // 4. 清除缓存，避免重复使用
108:     await this.orderCacheStoreRepository.clearAll();
109: 
110:     // 5. 计算商品原价
111:     this.calculateOriginalPrice();
112:   }
113: 
114:   /**
115:    * 将已选商品列表转换为购物车列表
116:    * @param {SelectedGoods[]} goodsList 已选商品列表
117:    * @returns {Cart[]} 购物车列表
118:    */
119:   private convertSelectedGoodsToCartList(goodsList: SelectedGoods[]): Cart[] {
120:     // 按商品ID分组
121:     const groupedMap = new Map<number, SelectedGoods[]>();
122: 
123:     for (const goods of goodsList) {
124:       const existingList = groupedMap.get(goods.goodsId);
125:       if (existingList) {
126:         existingList.push(goods);
127:       } else {
128:         groupedMap.set(goods.goodsId, [goods]);
129:       }
130:     }
131: 
132:     // 为每个商品ID创建一个Cart对象
133:     const result: Cart[] = [];
134: 
135:     groupedMap.forEach((items: SelectedGoods[], goodsId: number) => {
136:       const firstItem = items[0];
137: 
138:       const cart = new Cart();
139:       cart.goodsId = goodsId;
140:       cart.goodsName = firstItem.goodsInfo?.title ?? "";
141:       cart.goodsMainPic = firstItem.goodsInfo?.mainPic ?? "";
142: 
143:       // 收集该商品的所有规格
144:       const allSpecs: CartGoodsSpec[] = [];
145: 
146:       for (const selectedItem of items) {
147:         // 如果有规格信息，转换为CartGoodsSpec并添加
148:         if (selectedItem.spec) {
149:           const cartSpec = new CartGoodsSpec();
150:           cartSpec.id = selectedItem.spec.id;
151:           cartSpec.goodsId = selectedItem.spec.goodsId;
152:           cartSpec.name = selectedItem.spec.name;
153:           cartSpec.price = selectedItem.spec.price;
154:           cartSpec.stock = selectedItem.spec.stock;
155:           cartSpec.count = selectedItem.count;
156:           cartSpec.images = selectedItem.spec.images;
157:           allSpecs.push(cartSpec);
158:         }
159:       }
160: 
161:       cart.spec = allSpecs;
162:       result.push(cart);
163:     });
164: 
165:     return result;
166:   }
167: 
168:   /**
169:    * 是否从购物车来的
170:    * @returns {boolean} 是否从购物车来
171:    */
172:   get isFromCart(): boolean {
173:     return this.cachedCarts !== null && this.cachedCarts.length > 0;
174:   }
175: 
176:   /**
177:    * 购物车是否为空
178:    * @returns {boolean} 是否为空
179:    */
180:   get isEmpty(): boolean {
181:     return this.cartList.length === 0;
182:   }
183: 
184:   /**
185:    * 更新订单备注
186:    * @param {string} newRemark 新的备注内容
187:    * @returns {void} 无返回值
188:    */
189:   updateRemark(newRemark: string): void {
190:     this.remark = newRemark;
191:   }
192: 
193:   /**
194:    * 显示优惠券弹出层
195:    * @returns {void} 无返回值
196:    */
197:   showCouponModal(): void {
198:     this.couponModalVisible = true;
199:   }
200: 
201:   /**
202:    * 隐藏优惠券弹出层
203:    * @returns {void} 无返回值
204:    */
205:   hideCouponModal(): void {
206:     this.couponModalVisible = false;
207:   }
208: 
209:   /**
210:    * 选择优惠券
211:    * @param {Coupon | null} coupon 选中的优惠券，null表示不使用优惠券
212:    * @returns {void} 无返回值
213:    */
214:   selectCoupon(coupon: Coupon | null): void {
215:     this.selectedCoupon = coupon;
216:     this.hideCouponModal();
217:     this.calculatePrices();
218:   }
219: 
220:   /**
221:    * 计算商品原价
222:    * @returns {void} 无返回值
223:    */
224:   private calculateOriginalPrice(): void {
225:     let price = 0;
226:     for (const cart of this.cartList) {
227:       for (const spec of cart.spec) {
228:         price += spec.price * spec.count;
229:       }
230:     }
231:     this.originalPrice = price;
232:     this.calculatePrices();
233:   }
234: 
235:   /**
236:    * 计算价格（包括优惠券折扣）
237:    * @returns {void} 无返回值
238:    */
239:   private calculatePrices(): void {
240:     let discountValue = 0;
241: 
242:     if (this.selectedCoupon && this.selectedCoupon.condition) {
243:       // 检查是否满足使用条件
244:       if (this.originalPrice >= this.selectedCoupon.condition.fullAmount) {
245:         discountValue = this.selectedCoupon.amount ?? 0;
246:       }
247:     }
248: 
249:     this.discountAmount = discountValue;
250:     this.totalPrice = Math.max(this.originalPrice - discountValue, 0);
251:   }
252: 
253:   /**
254:    * 跳转到地址选择页面
255:    * @returns {void} 无返回值
256:    */
257:   navigateToAddressSelection(): void {
258:     UserNavigator.toAddressList(true)
259:       .then((result?: UserSelectAddressResult): void => {
260:         if (result?.address) {
261:           console.log(JSON.stringify(result.address))
262:         }
263:       });
264:   }
265: 
266:   /**
267:    * 提交订单点击事件
268:    * @returns {void} 无返回值
269:    */
270:   onSubmitOrderClick(): void {
271:     // TODO: 实现提交订单逻辑
272:   }
273: 
274:   /**
275:    * 删除购物车中已下单的商品
276:    * @returns {Promise<void>} Promise<void>
277:    */
278:   async deleteCartItems(): Promise<void> {
279:     if (!this.cachedCarts || this.cachedCarts.length === 0) {
280:       return;
281:     }
282: 
283:     for (const cart of this.cachedCarts) {
284:       const goodsId = cart.goodsId;
285: 
286:       // 获取该商品所有的规格ID
287:       const specIds = new Set(cart.spec.map((s: CartGoodsSpec): number => s.id));
288: 
289:       // 判断是否需要删除整个商品
290:       const fullCart = await this.cartRepository.getCartByGoodsId(goodsId);
291: 
292:       if (fullCart) {
293:         // 所有规格是否都在订单中
294:         const allSpecIds = new Set(fullCart.spec.map((s: CartGoodsSpec): number => s.id));
295: 
296:         if (specIds.size === allSpecIds.size) {
297:           // 删除整个商品
298:           await this.cartRepository.removeFromCart(goodsId);
299:         } else {
300:           // 逐个删除规格
301:           for (const specId of specIds) {
302:             await this.cartRepository.removeSpecFromCart(goodsId, specId);
303:           }
304:         }
305:       }
306:     }
307:   }
308: }
