31:    * @returns {Promise<NetworkResponse<T>>} 网络请求 Promise
32:    */
33:   protected abstract requestRepository(): Promise<NetworkResponse<T>>;
34: 
35:   /**
36:    * 页面出现时的生命周期回调
37:    * @returns {void} 无返回值
38:    */
39:   aboutToAppear(): void {
40:     this.executeRequest();
41:   }
42: 
43:   /**
44:    * 发起请求
45:    * @returns {void} 无返回值
46:    */
47:   executeRequest(): void {
48:     RequestHelper.repository<T>(this.requestRepository())
49:       .toast(this.showErrorToast)
50:       .start(() => this.onRequestStart())
51:       .execute()
52:       .then((data: T) => this.onRequestSuccess(data))
53:       .catch(() => this.onRequestError());
54:   }
55: 
56:   /**
