import { MainPage } from 'main';
import { RouteBuild, NAV_PATH_STACK_KEY, setNavPathStack } from 'navigation';

/**
 * @file 挂载全局导航栈
 * @author Joker.X
 */
@ComponentV2
export struct NavigationHost {
  /**
   * 导航栈
   */
  @Provider(NAV_PATH_STACK_KEY)
  navPathStack: NavPathStack = new NavPathStack();

  aboutToAppear(): void {
    setNavPathStack(this.navPathStack);
  }

  /**
   * 导航目标构建器
   * @param name 路由名称
   * @returns 路由构建器
   */
  @Builder
  PagesMap(name: string) {
    if (RouteBuild.getBuilder(name) !== undefined) {
      (RouteBuild.getBuilder(name) as WrappedBuilder<[]>).builder();
    }
  }

  /**
   * 导航目标构建器
   * @returns 路由构建器
   */
  build() {
    Navigation(this.navPathStack) {
      MainPage()
    }
    .hideTitleBar(true)
    .mode(NavigationMode.Stack)
    .navDestination(this.PagesMap)
  }
}

import common from "@ohos.app.ability.common";
import { getBreakpointState, getWindowSafeAreaState } from "state";
import { WindowAdapter } from "../adapter/WindowAdapter";

/**
 * @file 应用入口 ViewModel，负责沉浸式窗口、安全区与断点监听初始化
 * @author Joker.X
 */

export default class EntryViewModel {
  /**
   * 窗口能力适配器
   */
  private readonly windowAdapter: WindowAdapter = new WindowAdapter(
    getWindowSafeAreaState(),
    getBreakpointState()
  );

  /**
   * 入口页面初始化
   * 由 EntryPage.aboutToAppear 调用，统一触发窗口相关初始化
   * @param {Context} context - 组件上下文
   * @returns {void} 无返回值
   */
  aboutToAppear(context: common.Context): void {
    this.windowAdapter.init(context);
  }

  /**
   * 入口页面销毁
   * 由 EntryPage.aboutToDisappear 调用，释放窗口监听
   * @returns {void} 无返回值
   */
  aboutToDisappear(): void {
    this.windowAdapter.dispose();
  }
}

