  cartList: Cart[] = [];
  selectedGoodsList: SelectedGoods[] = [];
  isFromCart: boolean = false;
  originalPrice: number = 0;
  totalPrice: number = 0;
  uiState: string = '';
}

export class LocalAnalysisProbe {
  static enabled: boolean = false;
