import { NavigationHost } from '../navigation/NavigationHost';
import { LocalBaselineFixture } from '../localtest/LocalBaselineFixture';
import { getNavPathStack, OrderNavigator } from 'navigation';

/** Extra test banner is distinct from every original business control. */
@Entry
@ComponentV2
struct LocalBaselinePage {
  private timerId: number = -1;
  private attempts: number = 0;
  private entered: boolean = false;

  aboutToAppear(): void {
    this.timerId = setInterval((): void => {
      this.attempts++;
      if (LocalBaselineFixture.uiReady && LocalBaselineFixture.fixtureReady && getNavPathStack()) {
        clearInterval(this.timerId);
        this.timerId = -1;
        if (!this.entered) {
          this.entered = true;
          if (LocalBaselineFixture.entry === 'confirm') {
            OrderNavigator.toConfirm();
          }
          LocalBaselineFixture.log('ENTRY', `original-NavigationHost;entry=${LocalBaselineFixture.entry}`);
        }
      } else if (this.attempts >= 100) {
        clearInterval(this.timerId);
        this.timerId = -1;
        LocalBaselineFixture.log('ENTRY_ERROR', 'UI/fixture/navigation readiness timeout');
      }
    }, 50);
  }

  aboutToDisappear(): void {
    if (this.timerId >= 0) {
      clearInterval(this.timerId);
      this.timerId = -1;
    }
  }

  build() {
    Column() {
      Row() {
        Text(`本地调查 ${LocalBaselineFixture.scenario}/${LocalBaselineFixture.entry}`)
          .fontSize(12)
          .fontColor(Color.White)
          .layoutWeight(1)
          .id('local_fixture_identity');
        Button('本地诊断')
          .fontSize(12)
          .height(32)
          .id('local_probe_dump')
          .onClick((): void => {
            LocalBaselineFixture.dumpActual('manual').catch((error: Error): void => {
              LocalBaselineFixture.log('DIAGNOSTIC_ERROR', error.message);
            });
          });
      }
      .padding({ left: 8, right: 8, top: 26, bottom: 4 })
      .width('100%')
      .backgroundColor('#304568');
      NavigationHost().layoutWeight(1);
    }
    .width('100%')
    .height('100%');
  }
}

