    LocalBaselineFixture.entry = entry;
    LocalBaselineFixture.emptyAddressList = emptyAddressList;
  }

  static isActive(): boolean {
    return LocalBaselineFixture.scenario === 'with-address' || LocalBaselineFixture.scenario === 'no-address';
  }

  static log(kind: string, value: string): void {
    console.info(`[HCUP_LOCAL] ${kind} ${value}`);
  }

  private static address(id: number, contact: string, phone: string, detail: string, isDefault: boolean): Address {
    const value = new Address();
    value.id = id;
    value.contact = contact;
    value.phone = phone;
    value.province = '北京市';
    value.city = '北京市';
    value.district = '东城区';
    value.address = detail;
    value.isDefault = isDefault;
    return value;
  }

  private static spec(goodsId: number, id: number, price: number, count: number): CartGoodsSpec {
    const value = new CartGoodsSpec();
    value.id = id;
    value.goodsId = goodsId;
    value.name = `本地规格${id}`;
    value.price = price;
    value.count = count;
    value.stock = 100;
    value.images = [];
    return value;
  }

  private static carts(): Cart[] {
    const first = new Cart();
    first.goodsId = 1701;
    first.goodsName = '本地商品甲1701';
    first.goodsMainPic = '';
    first.spec = [LocalBaselineFixture.spec(1701, 11, 1250, 2),
      LocalBaselineFixture.spec(1701, 37, 2300, 1), LocalBaselineFixture.spec(1701, 91, 900, 4)];
    const second = new Cart();
    second.goodsId = 2903;
    second.goodsName = '本地商品乙2903';
    second.goodsMainPic = '';
    second.spec = [LocalBaselineFixture.spec(2903, 205, 800, 3),
      LocalBaselineFixture.spec(2903, 407, 450, 2)];
    const third = new Cart();
    third.goodsId = 4109;
    third.goodsName = '本地未选丙4109';
    third.goodsMainPic = '';
    third.spec = [LocalBaselineFixture.spec(4109, 4193, 600, 1)];
    return [first, second, third];
  }

  private static selectedGoods(carts: Cart[]): SelectedGoods[] {
    const result: SelectedGoods[] = [];
    for (const cart of carts) {
      for (const cartSpec of cart.spec) {
        if ((cart.goodsId === 1701 && cartSpec.id === 37) || cart.goodsId === 2903) {
          const selected = new SelectedGoods();
          selected.goodsId = cart.goodsId;
          selected.count = cartSpec.count;
          const spec = new GoodsSpec();
          spec.id = cartSpec.id;
          spec.goodsId = cartSpec.goodsId;
          spec.name = cartSpec.name;
          spec.price = cartSpec.price;
          spec.stock = cartSpec.stock;
          spec.images = [];
          selected.spec = spec;
          const goods = new Goods();
          goods.id = cart.goodsId;
          goods.title = cart.goodsName;
          goods.mainPic = '';
          selected.goodsInfo = goods;
          result.push(selected);
        }
      }
    }
    return result;
