  private static confirmData(): ConfirmOrder {
    const coupon = new Coupon();
    coupon.id = 503;
    coupon.title = '本地调查券503';
    coupon.amount = 300;
    coupon.status = 1;
    const condition = new Condition();
    condition.fullAmount = 1000;
    coupon.condition = condition;
    const data = new ConfirmOrder();
    data.defaultAddress = LocalBaselineFixture.defaultAddress;
    data.userCoupon = [coupon];
    return data;
  }

  static async prepare(): Promise<void> {
    if (!LocalBaselineFixture.isActive()) {
      throw new Error('Local fixture requires an explicit whitelisted Want scenario');
    }
    LocalAnalysisProbe.enabled = true;
    NetworkClient.http.defaults.adapter =
      (config: InternalAxiosRequestConfig): Promise<AxiosResponse<Object>> => LocalBaselineFixture.adapt(config);
    // This change is in memory, only in the separate test bundle's explicit test launch.
    removeLoginRequiredRoute(OrderRoutes.Confirm);
    removeLoginRequiredRoute(UserRoutes.AddressList);
    removeLoginRequiredRoute(UserRoutes.AddressDetail);
    const first = LocalBaselineFixture.address(701, '本地默认甲', '13800000001', '本地测试甲路701号', true);
    const second = LocalBaselineFixture.address(907, '本地选择乙', '13800000002', '本地测试乙路907号', false);
    LocalBaselineFixture.defaultAddress = LocalBaselineFixture.scenario === 'with-address' ? first : null;
    LocalBaselineFixture.addresses = LocalBaselineFixture.emptyAddressList ? [] :
      (LocalBaselineFixture.scenario === 'with-address' ? [first, second] : [second]);
    const cartRepository = new CartRepository();
    const carts = LocalBaselineFixture.carts();
    // Reset only our synthetic goods IDs, in the separate bundle's own app.db.
    for (const cart of carts) {
      await cartRepository.removeFromCart(cart.goodsId);
      await cartRepository.addToCart(cart);
    }
    const cache = new OrderCacheStoreRepository();
    await cache.clearAll();
    if (LocalBaselineFixture.entry === 'confirm') {
      // Direct-purchase-shaped cache injection, not a claim that goods-detail UI was used.
      await cache.saveSelectedGoodsList(LocalBaselineFixture.selectedGoods(carts));
    }
    LocalBaselineFixture.fixtureReady = true;
    LocalBaselineFixture.log('READY', `scenario=${LocalBaselineFixture.scenario};entry=${LocalBaselineFixture.entry};` +
      'adapter=local-only;tokenWritten=false;source=synthetic-local-fixture-v1');
    await LocalBaselineFixture.dumpActual('seed-complete');
  }

  private static async adapt(config: InternalAxiosRequestConfig): Promise<AxiosResponse<Object>> {
    const event = new LocalRequestEvent();
    event.sequence = LocalBaselineFixture.requests.length + 1;
    event.method = (config.method ?? 'GET').toUpperCase();
    event.path = (config.url ?? '').replace(/^\/+/, '').split('?')[0];
    event.body = typeof config.data === 'string' ? config.data : JSON.stringify(config.data) ?? '';
    event.hasAuthorization = Boolean(config.headers.get('Authorization'));
    LocalBaselineFixture.requests.push(event);
    let payload: Object;
    if (event.method === 'GET' && event.path === 'page/confirmOrder') {
      LocalBaselineFixture.confirmCount++;
      await new Promise<void>((resolve) => { setTimeout(resolve, 150); });
      payload = new NetworkResponse<ConfirmOrder>({ code: 1000, data: LocalBaselineFixture.confirmData(), message: null });
      event.outcome = 'LOCAL_CONFIRM_FIXTURE';
    } else if (event.method === 'POST' && event.path === 'user/address/page') {
      LocalBaselineFixture.addressPageCount++;
      const page = new NetworkPageData<Address>();
      page.list = LocalBaselineFixture.addresses.slice();
      page.pagination = new NetworkPageMeta({ page: 1, size: 10, total: page.list.length });
      payload = new NetworkResponse<NetworkPageData<Address>>({ code: 1000, data: page, message: null });
      event.outcome = 'LOCAL_ADDRESS_LIST_FIXTURE';
    } else if (event.method === 'POST' && event.path === 'user/address/add') {
      LocalBaselineFixture.addressAddCount++;
      const parsed = JSON.parse(event.body) as Address;
      const address = new Address(parsed);
      address.id = LocalBaselineFixture.nextAddressId++;
      LocalBaselineFixture.addresses.push(address);
      const data: Record<string, number> = { 'id': address.id };
      payload = new NetworkResponse<Record<string, number>>({ code: 1000, data: data, message: null });
      event.outcome = 'LOCAL_ADDRESS_ADD_FIXTURE';
    } else {
      if (event.method === 'POST' && event.path === 'order/info/create') {
        LocalBaselineFixture.createCount++;
        event.outcome = 'LOCAL_CREATE_REJECTED_NO_ORDER_CREATED';
      } else {
        event.outcome = 'LOCAL_UNKNOWN_REJECTED';
      }
      LocalBaselineFixture.rejectCount++;
      LocalBaselineFixture.log('REQUEST', JSON.stringify(event));
      throw new Error(`HCUP_LOCAL_ONLY rejected ${event.method} ${event.path}`);
    }
    LocalBaselineFixture.log('REQUEST', JSON.stringify(event));
    const response: AxiosResponse<Object> = {
      data: payload, status: 200, statusText: 'LOCAL_FIXTURE', headers: new AxiosHeaders(), config: config
    };
    return response;
  }

  static async dumpActual(reason: string): Promise<void> {
    const snapshot = new LocalRuntimeSnapshot();
    snapshot.reason = reason;
    snapshot.scenario = LocalBaselineFixture.scenario;
    snapshot.entry = LocalBaselineFixture.entry;
    snapshot.addressListMode = LocalBaselineFixture.emptyAddressList ? 'initially-empty' : 'seeded';
    snapshot.routeNames = getNavPathStack()?.getAllPathName() ?? [];
    snapshot.order = LocalAnalysisProbe.readOrder();
    const cartRepository = new CartRepository();
    snapshot.carts = await cartRepository.getAllCarts();
    const cache = new OrderCacheStoreRepository();
    snapshot.cacheCarts = await cache.loadCarts();
    snapshot.cacheSelectedGoods = await cache.loadSelectedGoodsList();
    snapshot.confirmCount = LocalBaselineFixture.confirmCount;
    snapshot.addressPageCount = LocalBaselineFixture.addressPageCount;
    snapshot.addressAddCount = LocalBaselineFixture.addressAddCount;
    snapshot.createCount = LocalBaselineFixture.createCount;
    snapshot.rejectCount = LocalBaselineFixture.rejectCount;
    snapshot.requests = LocalBaselineFixture.requests;
    // Separate records keep the large real VM/DB readout within hilog record limits.
    LocalBaselineFixture.log('STATE', JSON.stringify(snapshot));
    LocalBaselineFixture.log('ORDER_ACTUAL', JSON.stringify(snapshot.order));
    LocalBaselineFixture.log('CARTS_ACTUAL', JSON.stringify(snapshot.carts));
    LocalBaselineFixture.log('COUNTS', `confirm=${snapshot.confirmCount};addressPage=${snapshot.addressPageCount};` +
      `addressAdd=${snapshot.addressAddCount};create=${snapshot.createCount};reject=${snapshot.rejectCount};` +
      `routes=${JSON.stringify(snapshot.routeNames)}`);
  }
}

